INSERT INTO public.theme_registry (key, name_en, name_bn, summary_en, summary_bn, category, version, preset, active, sort_order) VALUES ('clothing-heritage', 'Clothing Heritage', 'ক্লোদিং হেরিটেজ', 'Aarong-grade heritage clothing storefront with mega menus, artisan stories, lookbooks and fit guides.', 'মেগা মেনু, তাঁতির গল্প, লুকবুক ও ফিট গাইডসহ আড়ং-মানের ঐতিহ্যবাহী পোশাক স্টোরফ্রন্ট।', 'fashion', '1.0.0', '{"tokens":{"brand":"#1A1A1A","accent":"#C45D3E","surface":"#FAF8F5","ink":"#2D2A26","radius":"2px","fontDisplay":"Playfair Display","fontBody":"Inter","container":"1320px","density":"airy","typeScale":"expressive","spaceUnit":"16px","shadow":"soft","motion":"subtle","digits":"latin","locale":"en","currencyDisplay":"symbol","fontPairing":"editorial-serif","dark":{"brand":"#FAF8F5","accent":"#D4784A","surface":"#1A1816","ink":"#F0EDE8"},"globals":{"colors":[{"id":"primary","name":"Primary","value":"#0F766E"},{"id":"secondary","name":"Secondary","value":"#0D9488"},{"id":"text","name":"Text","value":"#0F172A"},{"id":"surface","name":"Surface","value":"#FFFFFF"}],"fonts":[{"id":"heading","name":"Headings","family":"Noto Sans Bengali","weight":"700"},{"id":"body","name":"Body","family":"Noto Sans Bengali","weight":"400"}]},"timezone":"Asia/Dhaka","allowCustomerTimezone":false},"templates":{"index":{"header":[{"id":"clothing-heritage-subbrand-bar-1","type":"subbrand_bar","props":{"activeBrand":"Aarong","tagline":"A Social Enterprise","b1Name":"Aarong","b1Href":"/","b2Name":"Taaga","b2Href":"/collections/taaga","b3Name":"Taaga Man","b3Href":"/collections/taaga-man","b4Name":"Herstory","b4Href":"/collections/herstory","b5Name":"Aarong Earth","b5Href":"/collections/beauty","tagline_bn":"একটি সামাজিক উদ্যোগ","b1Name_bn":"আড়ং","b2Name_bn":"তাগা","b3Name_bn":"তাগা ম্যান","b4Name_bn":"হারস্টোরি","b5Name_bn":"আড়ং আর্থ"}},{"id":"clothing-heritage-announcement-bar-2","type":"announcement_bar","props":{"m1":"Free nationwide delivery on orders over BDT 3,000","m2":"Eid & Festive